package policy; import java.util.ArrayList;import java.util.HashMap;import java.util.List;import java.util.Map; public final class RuleOrderingAnalyzer{public List<DuplicateFinding> duplicates(PolicyDocument doc){List<DuplicateFinding> out=new ArrayList<>();Map<String,Integer> seen=new HashMap<>();int i=0;for(FirewallRule r:doc.rules()){String k=r.key();if(seen.containsKey(k))out.add(new DuplicateFinding(seen.get(k),i));else seen.put(k,i);i++;}return out;}public List<ShadowFinding> shadowed(PolicyDocument doc){List<ShadowFinding> out=new ArrayList<>();java.util.List<FirewallRule> rules=doc.rules();for(int i=0;i<rules.size();i++){FirewallRule a=rules.get(i);for(int j=0;j<i;j++){FirewallRule b=rules.get(j);if(b.chain().equals(a.chain())&&b.protocol().equals(a.protocol())&&b.source().equals("any")&&b.destination().equals("any")&&b.destinationPort().contains(a.destinationPort().start())&&b.destinationPort().contains(a.destinationPort().end())){out.add(new ShadowFinding(i,j,"earlier broad rule covers later rule"));break;}}}return out;}}
